[meta]
name = Harrowmere
ambient = 0.2 0.19 0.22
fog = 0.11 0.11 0.13
fog_range = 6 34
model_range = 36
sky = dusk
atlas = harrowmere
torch = 4 0.5 0.42 0.36
start = 2 22 0
default = ,
edge_top = -0.5
open_sea = true
entity_floor = auto

// Harrowmere under a low, sooty dusk, its trees dead and its streets still strewn with what fell when
// the town was ruined: a walled town laid out square, one gate to each road. You come
// in by the cemetery's gate in the west wall, down the west avenue to the round plaza at the heart of
// town, where the Silent Bell hangs on its plinth by the shrine. North of the plaza the cathedral stands
// on its terrace two metres up, its great door facing south down the grand stair, the Enthroned at the
// end of the nave. The west side is the craftsmen's and the watch's: Corvane's house and Brannoc's forge
// on the north road's street, the walled garden behind them, and south of the avenue the gaol yard,
// where the old gaol's barred pit drops into the Abandoned Prison, and the watch office. The east side
// is the traders': Tamsin's hall and Pell's house on the Vesper street, the carters' yard by the east
// gate. South-east, a little neighbourhood of five houses round a lane; south-west, Wren's house and
// the founder's chapel against the wall beside the watch office. The north road leaves by the gate in the north wall's west end, Vesperholm through
// the Vesper Gate at its east end, the green trail through the east gate for the cave, and the south
// street through the sea gate onto the quay, where Maeve fishes off the end of the pier. A sewer grate
// in each corner of the town drops into the Harrow Sewers.

[legend]
R = wall tex=soot_ashlar top=7 cap=soot_ashlar dress=rampart
A = wall tex=cliff_rock top=6 cap=rough_stone
// The houses' thin walls: dressed stone (H) and half-timbering over an ashlar ground floor (#). All
// the town's stone, its wall, its houses, the cathedral and the terrace it stands on, is one dressed ashlar blackened by the burning.
H = wall tex=soot_ashlar top=5.6 cap=roof thin=0.5
# = wall tex=stone_timber top=5.6 cap=roof thin=0.5
// The stone stack in the elbow of Pell's L, its chimney rising from it: a full wall, so both of the
// thin runs that meet there end against it.
^ = wall tex=soot_ashlar top=5.6 cap=roof
C = wall tex=soot_ashlar h=2 top=11 cap=slate
P = wall tex=flagstone top=0.8 cap=flagstone
// The parapet round the cathedral's terrace, and the gaol yard's wall.
[ = wall tex=soot_ashlar top=2.7 cap=flagstone
] = wall tex=soot_ashlar top=3.2 cap=flagstone
, = floor tex=cobble h=0
. = floor tex=cobble h=0
s = floor tex=setts h=0
- = floor tex=setts h=0
// The flagged kerbs raised along the avenues and the streets, the garden's earth gate and its dead,
// ash-grey grass.
/ = floor tex=flagstone h=0.15 side=flagstone
_ = floor tex=dirt h=0 side=soot_ashlar
G = floor tex=ash_grass h=0 side=soot_ashlar
// The plaza's flagstones, round the bell, and the quay's outside the sea gate.
e = floor tex=flagstone h=0 side=soot_ashlar
t = floor tex=flagstone h=0 side=soot_ashlar
// The cathedral's terrace, two metres up, and the grand stair down from it: each tile half a metre
// below the last, its fine steps drawn over it.
; = floor tex=flagstone h=2 side=soot_ashlar
4 = floor tex=flagstone h=1.5 side=soot_ashlar
3 = floor tex=flagstone h=1.0 side=soot_ashlar
2 = floor tex=flagstone h=0.5 side=soot_ashlar
1 = floor tex=flagstone h=0 side=soot_ashlar
n = floor tex=cathedral_floor h=2 ceil=10 ceil_tex=slate side=soot_ashlar dark=0.3
a = floor tex=cathedral_floor h=2.4 ceil=10 ceil_tex=slate side=soot_ashlar dark=0.3
i = floor tex=wood_plank h=0.2 ceil=3.4 ceil_tex=wood_plank side=wood_plank
k = floor tex=flagstone h=0 ceil=3.4 ceil_tex=wood_plank side=soot_ashlar
// The founder's chapel's flagged floor, under a ceiling high enough for his statue.
Ċ = floor tex=flagstone h=0 ceil=4.6 ceil_tex=wood_plank side=soot_ashlar dark=0.35
// The cheek walls either side of the cathedral's grand stair, each stepping down with the stair
// beside it: its top is the top of that tile's highest step, and the stair's balustrade rakes along it.
9 = wall tex=soot_ashlar top=2.0 cap=flagstone
8 = wall tex=soot_ashlar top=1.5 cap=flagstone
7 = wall tex=soot_ashlar top=1.0 cap=flagstone
6 = wall tex=soot_ashlar top=0.5 cap=flagstone
p = floor tex=wood_plank h=0.1 side=wood_plank
// The open sea off the quay and the pier is deep: whoever goes in drowns.
~ = water tex=water h=-0.8 side=soot_ashlar deep
V = wall tex=vine_wall top=5.5 cap=canopy
w = floor tex=jungle_floor h=0 ceil=4.2 ceil_tex=canopy side=vine_wall dark=0.2
y = floor tex=jungle_floor h=0 ceil=3.8 ceil_tex=canopy side=vine_wall dark=0.4
v = floor tex=jungle_floor h=0
c = floor tex=rough_stone h=0 ceil=3.4 ceil_tex=cliff_rock side=cliff_rock dark=0.45

