B = silent_bell on=P
S = save_statue
X = lamp_post
// The cathedral: its roof, the spire over the crossing, twin towers either side of its front and two
// turrets at the apse, flying buttresses, stained glass within and without (in pairs, one pair to
// each bay between the buttresses outside), the great door (three tiles wide) with the great rose in
// the gable over it and another rose above the throne, pillars, pews facing the throne, a crimson
// runner up the nave, candles and banners. Its floor is marble lozenges in bordered panels. Its roofs
// stay dark slate, so the hilltop stands out over the town's clay.
É = roof span=7,10 ridge=z top=9 pitch=3.5 tex=clay_tile wall=soot_ashlar on=C
Ê = cathedral_spire height=15 base=11 on=n
è = cathedral_tower height=15 shift=-1,1 on=C
é = cathedral_tower height=15 shift=1,1 on=C
ê = cathedral_tower height=10 width=2.2 helm=4 turret shift=-2,0 on=C
ë = cathedral_tower height=10 width=2.2 helm=4 turret shift=2,0 on=C
ï = cathedral_portal yaw=90 height=9 rose=10.6 on=n
// The runner is laid in two stretches, one to each bake chunk, so neither drops from sight.
: = nave_runner length=3 ends=head yaw=90 on=n
` = nave_runner length=3 ends=foot yaw=90 on=n
î = rose_window rise=5.6 on=a
ì = stained_window
í = flying_buttress
ð = light y=4 color=0.95,0.3,0.32 radius=6 on=n
ñ = light y=4 color=0.35,0.45,1.0 radius=6 on=n
ò = light y=4 color=1.0,0.78,0.3 radius=6 on=n
ó = light y=4 color=0.35,0.9,0.5 radius=6 on=n
// The grand stair down from the porch to the plaza: four tiles of fine steps between raking
// balustrades on the cheek walls, lanterns on the newels at its head (it casts their light), urns at
// its foot. A pale light on the porch, so the great door's carving shows from the plaza.
" = grand_stair run=4 rise=0.5 steps=5 width=3 yaw=90 on=4
¬ = light y=5 color=0.78,0.74,0.7 radius=9 on=;
I = pillar
Q = pew yaw=-90
