ş = roof span=5,5 ridge=z top=5.6 pitch=3.4 eave=0.45 tex=clay_tile wall=soot_ashlar on=H
Š = roof span=5,5 ridge=x top=5.6 pitch=3.2 eave=0.45 hip=true tex=clay_tile wall=soot_ashlar on=H
Ñ = chimney height=8 on=H
Ď = chimney height=7.5 on=^
Ā = jetty len=7 rise=3 height=2.4
ā = dormer y=5.6 yaw=-90 on=#
// Round turrets corbelled out from the houses' corners under witch-hat cones of clay tile.
¡ = roof_turret shift=0.8,-0.8 roof_tex=clay_tile on=H
¤ = roof_turret shift=0.8,0.8 roof_tex=clay_tile on=H
« = roof_turret shift=-0.8,0.8 roof_tex=clay_tile on=H
// The houses' faces: shuttered windows, balconies and arched front doors. Each house's windows are
// set either side of its door, or of the middle of a wall without one, and share one look (`seed=`
// sets their paint, grille and shutters): Brannoc's (Ē), Pell's (ē), Wren's (Ĕ), Tamsin's (ĕ), the
// watch office's (ŕ) and the neighbourhood's (Ţ ţ Ť ť Ŧ); Corvane's house keeps one plain window in the
// middle of its north and south walls (à). Corvane's and two of the neighbourhood's (ţ, Ŧ) are boarded
// up, dark behind their planks, a shutter hanging off its last hinge (`broken`).
à = shutters broken
Ē = shutters seed=8
ē = shutters seed=0
Ĕ = shutters seed=6
ĕ = shutters seed=11
ŕ = shutters seed=3
Ţ = shutters seed=2
ţ = shutters seed=4 broken
Ť = shutters seed=5
ť = shutters seed=9
Ŧ = shutters seed=13 broken
ä = door_arch yaw=0 on=i
æ = door_arch yaw=-90 on=i
š = door_arch yaw=90 on=i
¹ = door_arch yaw=0 on=k
// The realm's crest: banners on poles about the plaza, sooted and rotting since the town fell, one
// torn half off its crossbar and one gone but for a knotted scrap; and carved on the gaol yard's wall.
Þ = banner_pole style=whole
Ŏ = banner_pole style=torn
ŏ = banner_pole style=bare
ß = crest_plaque
// The market's fountain, foul and still, its cracked benches, and the carts and cargo hauled up from
// the quay and left to rot when the town fell.
Ô = fountain
Õ = bench yaw=0
Ö = bench yaw=180
Ù = bench yaw=-90
Û = hand_cart
Ü = hay_wagon yaw=-90
Ý = cargo
// The founder's chapel, a little house of worship built against the west wall by the watch office,
// its door facing the square by Wren's house: the founder's statue in bronze, gone green, stands at
// its far end against the wall he raised, an altar crowded with candles before it and more burning
// either side, two pews before them, and Old Berthe, who keeps its candles, at prayer in one.
Ĝ = roof span=7,5 ridge=x top=5.6 pitch=3.4 eave=0.45 tex=clay_tile wall=soot_ashlar on=H
Č = door_arch yaw=0 on=Ċ
¨ = town_statue yaw=0 on=Ċ
Ă = founder_altar yaw=0 on=Ċ
Ġ = candles on=Ċ
ğ = pew yaw=180 on=Ċ
// The town wall's round towers, of the town's sooty stone under oxblood tile: its corners, along the walls, the two either
// side of the sea gate and the two at the moles' ends.
® = wall_tower shift=-0.8,-0.8 radius=1.8 on=R
¯ = wall_tower shift=0,-0.8 radius=1.8 on=R
° = wall_tower shift=0.8,-0.8 radius=1.8 on=R
± = wall_tower shift=-0.8,0 radius=1.8 on=R
² = wall_tower shift=0.8,0 radius=1.8 on=R
ŝ = wall_tower shift=0,0.8 radius=1.8 on=R
³ = wall_tower shift=-0.8,0.8 radius=2.2 height=9 on=R
´ = wall_tower shift=0.8,0.8 radius=2.2 height=9 on=R
// The sea gate: a crenellated arch over the south street where it passes through the wall.
Ŝ = street_arch yaw=90 width=3 style=crenel on=s
// The shops' signs, each hung from an iron bracket by its door and painted with what it sells:
// Brannoc's anvil by the forge's door, Pell's scroll, Tamsin's flask and Corvane's crossed blades.
þ = shop_sign emblem=anvil
µ = shop_sign emblem=scroll
¶ = shop_sign emblem=flask on=s
· = shop_sign emblem=blades
