| = fence
@ = boat on=~
// The town's trees, long dead in the ash: bare, grey limbs clawing at the sky.
T = tree kind=dead
ø = tree kind=dead
// By the carters' yard on the east side, one of them caught alight and still burning, lighting the
// street red, a charred beam fallen from it (Ç).
Ć = burning_tree
ù = tree kind=dead
// The gate of the Cemetery of Ashes in the west wall: the Ashen come through it into town, and it
