ü = cemetery_gate yaw=0 sentinels=false
// A cold grey light falling on it, so its stone shows against the dark beyond.
¿ = light y=4.5 color=0.5,0.52,0.62 radius=7
// The old gaol's pit down into the Abandoned Prison, barred over with an iron grate in the middle of
// its walled yard south of the west avenue.
W = exit map=abandoned_prison at=15,32,-90 label=Descend_the_grate model=gaol_grate on=e
